use vstd::prelude::*;

verus! {

#[derive(Clone)]
struct Interval {
    start: f32,
    end: f32,
}

#[derive(Clone)]
struct Laguerre {
    coefficients: Vec<f32>,
    domain: Interval,
    window: Interval,
}

spec fn interval_well_formed(i: &Interval) -> bool {
    0.0 <= i.start && i.start <= i.end && i.end <= 1.0
}

fn make_laguerre(coefficients: Vec<f32>) -> (l: Laguerre)
    ensures
        // The output Laguerre's coefficients equals the input vector
        l.coefficients == coefficients,
        // The domain is [0.0, 1.0]
        l.domain.start == 0.0 && l.domain.end == 1.0,
        // The window is [0.0, 1.0]
        l.window.start == 0.0 && l.window.end == 1.0,
        // The domain and window intervals are well-formed
        interval_well_formed(&l.domain),
        interval_well_formed(&l.window),
{
    Laguerre {
        coefficients,
        domain: Interval { start: 0.0, end: 1.0 },
        window: Interval { start: 0.0, end: 1.0 },
    }
}

}

